    function testFuzz_property(address from, uint256 n, uint256 val) public {
        uint256 len = bound(n, 1, 5);

        address[] memory tos = new address[](len);
        uint256[] memory vs = new uint256[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(new Reverter());
            vs[i] = val;
        }

        bool okRef;
        bool retRef;
        try c.transfer(from, address(tos[0]), tos, vs) returns (bool r) {
            okRef = true;
            retRef = r;
        } catch {
            okRef = false;
            retRef = false;
        }

        assertTrue(okRef && retRef);
    }
}

